// Generates TypeScript types from the OpenAPI files in spec/ - the vendored TMF specs the
// UI uses and our own internal API - into src/api/generated/. Never from the app's
// /openapi.json: the contract is spec/. The output is git-ignored and regenerated by every
// build, lint and test run, so it cannot go stale.
//
// spec/ is mounted read-only at /spec in the web container (SPEC_DIR overrides it).
import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import openapiTS, { astToString } from 'openapi-typescript';

const SPEC_DIR = process.env.SPEC_DIR ?? '/spec';
const OUT_DIR = new URL('../src/api/generated/', import.meta.url);

// TMF676 (Swagger 2.0) is not used by the UI: payments reach it through the internal
// transactions view.
const SPECS = {
  tmf620: 'TMF620-Product_Catalog_Management-v5.0.0.oas.yaml',
  tmf622: 'TMF622-ProductOrdering-v5.0.0.oas.yaml',
  tmf629: 'TMF629-Customer_Management-v5.0.1.oas.yaml',
  tmf637: 'TMF637-ProductInventory-v5.0.0.oas.yaml',
  tmf666: 'TMF666-Account_Management-v5.0.0.oas.yaml',
  internal: 'internal/bss-internal.oas.yaml',
};

mkdirSync(OUT_DIR, { recursive: true });
for (const [name, file] of Object.entries(SPECS)) {
  const ast = await openapiTS(pathToFileURL(join(SPEC_DIR, file)));
  const header = `// GENERATED from spec/${file} by scripts/gen-types.mjs - do not edit.\n`;
  writeFileSync(new URL(`${name}.ts`, OUT_DIR), header + astToString(ast));
}
console.log(`types: ${Object.keys(SPECS).join(', ')} -> src/api/generated/`);
